-- ACMP курсының VI-IX бөлімдері: функциялар, сұрыптау, екі өлшемді массивтер және рекурсия.
-- Әр дәрісте қазақша және орысша нұсқа, PDF есептер тізімі және жасырын шешім бар.

do $acmp_advanced$
declare
  v_course uuid;
  v_school uuid;
  v_owner uuid;
  v_module uuid;
  v_lesson uuid;
  v_spec record;
  v_slides jsonb;
  v_plan jsonb;
  v_terms jsonb;
begin
  select c.id, c.school_id, c.owner_id into v_course, v_school, v_owner
  from public.cf_curr_courses c
  where c.id = 'dbe60970-1fa6-4a8a-a65e-051d20cfd278'
    and c.title = 'ACMP: Язык программирования C++';
  if v_course is null then raise exception 'ACMP курсы табылмады'; end if;

  for v_spec in select * from jsonb_to_recordset($spec$
  [
    {
      "module":"Функции","title":"Функциялар - 1","title_ru":"Функции - 1","position":0,"grade":8,"duration":"60 минут",
      "summary":"Функцияны бөлек блок ретінде құру, параметр беру және қайтарылатын мәнді пайдалану.","summary_ru":"Создание функции, передача параметров и использование возвращаемого значения.",
      "theory":["Функция бір әрекетті атау арқылы қайта қолдануға мүмкіндік береді.","Параметрлер жақша ішінде жазылады, return нәтиже қайтарады.","Функцияны main-нен бұрын жариялауға немесе прототип арқылы алдын ала сипаттауға болады.","Бір функция бір анық міндетті орындаса, код түсінікті болады."],
      "theory_ru":["Функция позволяет дать действию имя и повторно использовать его.","Параметры записываются в скобках, return возвращает результат.","Функцию можно описать до main или объявить прототипом заранее.","Пусть одна функция решает одну понятную задачу."],
      "algorithm":["Қайталанатын әрекетті анықтаңыз.","Функцияның параметрлері мен қайтару типін таңдаңыз.","Функция денесінде есепті орындап, return жазыңыз.","main ішінде функцияны қажетті аргументтермен шақырыңыз."],
      "algorithm_ru":["Найдите повторяющееся действие.","Выберите параметры и тип возвращаемого значения.","Выполните действие внутри функции и используйте return.","Вызовите функцию из main с нужными аргументами."],
      "code":"#include <iostream>\nusing namespace std;\nbool isDigit(char c) { return c >= '0' && c <= '9'; }\nint main() {\n    char a, b, c; cin >> a >> b >> c;\n    cout << isDigit(a) + isDigit(b) + isDigit(c);\n}",
      "tasks":["A. Цифрлар саны","B. Әріптерді санау","C. Терулер саны","D. Жай сандардың қосындысы","E. Тікбұрышты үшбұрыш","F. Үшбұрыштың ауданы"],
      "tasks_ru":["A. Количество цифр","B. Подсчёт букв","C. Число сочетаний","D. Сумма простых чисел","E. Прямоугольный треугольник","F. Площадь треугольника"],
      "statement":"Үш символ берілген. Олардың қаншасы цифр екенін анықтаңыз. Есепті шешу үшін C символы цифр болса 1, әйтпесе 0 қайтаратын IsDigit(C) функциясын жазыңыз.\n\nКіріс деректері: бос орынмен бөлінген үш символ. ASCII кодтары 32-ден үлкен.\n\nШығыс деректері: цифрлардың санын шығарыңыз.\n\nМысал: Кіріс: A % 5. Шығыс: 1.",
      "statement_ru":"Даны три символа. Определите, сколько из них являются цифрами. Реализуйте функцию IsDigit(C), возвращающую 1, если C — цифра, и 0 иначе.\n\nВходные данные: три символа, разделённые пробелами. Их ASCII-коды больше 32.\n\nВыходные данные: выведите количество цифр.\n\nПример: вход: A % 5. Выход: 1.",
      "explanation":"Негізгі тексеру бір жерде — IsDigit функциясында жазылады. Үш символдың әрқайсысын функцияға беріп, қайтарылған 0 немесе 1 мәндерін қосамыз.","explanation_ru":"Проверка записана в одном месте — в функции IsDigit. Передаём ей каждый символ и складываем возвращаемые значения 0 или 1.",
      "data":"char: a, b, c; bool функциясы: isDigit.","data_ru":"char: a, b, c; функция bool: isDigit.","pseudo":"оқу a, b, c\nIsDigit(c): егер c цифр болса 1, әйтпесе 0\nжауап ← IsDigit(a)+IsDigit(b)+IsDigit(c)\nшығару жауап","pseudo_ru":"прочитать a, b, c\nIsDigit(c): если c — цифра, вернуть 1, иначе 0\nanswer ← IsDigit(a)+IsDigit(b)+IsDigit(c)\nвывести answer",
      "solution":"#include <iostream>\nusing namespace std;\nbool IsDigit(char c) { return c >= '0' && c <= '9'; }\nint main() { char a,b,c; cin >> a >> b >> c; cout << IsDigit(a)+IsDigit(b)+IsDigit(c); }"
    },
    {
      "module":"Функции","title":"Функциялар - 2","title_ru":"Функции - 2","position":1,"grade":8,"duration":"75 минут",
      "summary":"Бірнеше функцияны біріктіру, рекурсивті емес көмекші функциялар және күрделі есепті бөліктерге бөлу.","summary_ru":"Комбинирование функций и разбиение сложной задачи на независимые вспомогательные части.",
      "theory":["Күрделі есепті бірнеше шағын функцияға бөлу қателерді азайтады.","Функциялар бір-бірін шақыра алады, бірақ циклдік шақырудан сақ болыңыз.","Мән бойынша параметр функцияға көшірме береді, сілтеме арқылы өзгертуге болады.","Функция атауы оның не істейтінін білдіргені дұрыс."],
      "theory_ru":["Разбиение сложной задачи на небольшие функции уменьшает количество ошибок.","Функции могут вызывать друг друга, но избегайте бесконечных циклических вызовов.","Параметр по значению передаёт копию, а ссылка позволяет изменить исходную переменную.","Имя функции должно объяснять её действие."],
      "algorithm":["Есептің тәуелсіз әрекеттерін бөліңіз.","Әр әрекетке жеке функция жазыңыз.","Негізгі функцияда нәтижелерді дұрыс ретпен біріктіріңіз.","Әр функцияны жеке қарапайым тестпен тексеріңіз."],
      "algorithm_ru":["Разделите задачу на независимые действия.","Для каждого действия напишите отдельную функцию.","В main объедините результаты в правильном порядке.","Проверьте каждую функцию отдельным простым тестом."],
      "code":"#include <iostream>\nusing namespace std;\nint digitSum(int n) {\n    int s = 0;\n    while (n > 0) { s += n % 10; n /= 10; }\n    return s;\n}\nbool isLucky(int n) { return digitSum(n / 1000) == digitSum(n % 1000); }\nint main() { int n; cin >> n; cout << (isLucky(n) ? \"YES\" : \"NO\"); }",
      "tasks":["A. Бақытқа бір қадам қалғанда","B. Массив үстіндегі қарапайым операциялар","C. Гольдбах гипотезасы","D. Бақытты билет - 2","E. Үшбұрыш және нүкте","F. Қате қосу"],
      "tasks_ru":["A. В одном шаге от счастья","B. Простые операции над массивом","C. Гипотеза Гольдбаха","D. Счастливый билет - 2","E. Треугольник и точка","F. Неправильное сложение"],
      "statement":"Алты цифрлы билет берілген. Билет бақытты деп аталады, егер алғашқы үш цифрдың қосындысы соңғы үш цифрдың қосындысына тең болса. Бірнеше билет үшін тексеру функцияларын қолданып, бақытты билет екенін анықтаңыз.\n\nКіріс деректері: бірінші жолда K тест саны, келесі K жолда алты цифрлы билет нөмірі беріледі.\n\nШығыс деректері: әр билет үшін YES немесе NO шығарыңыз.\n\nМысал: Кіріс: 1 123321. Шығыс: YES.",
      "statement_ru":"Дан шестизначный номер билета. Билет счастливый, если сумма первых трёх цифр равна сумме последних трёх. Для нескольких билетов используйте вспомогательные функции.\n\nВходные данные: в первой строке K, затем K шестизначных номеров билетов.\n\nВыходные данные: для каждого билета выведите YES или NO.\n\nПример: вход: 1 123321. Выход: YES.",
      "explanation":"digitSum функциясы санның цифрларының қосындысын табады, ал isLucky алғашқы және соңғы үш цифрды салыстырады. Негізгі код тек енгізу мен шығару ретін басқарады.","explanation_ru":"Функция digitSum находит сумму цифр числа, а isLucky сравнивает первые и последние три цифры. В main остаётся только ввод и вывод.",
      "data":"int: ticket, tests; функциялар: digitSum, isLucky.","data_ru":"int: ticket, tests; функции: digitSum, isLucky.","pseudo":"digitSum(n): цифрларды бөліп, қосу\nisLucky(n): digitSum(n/1000)=digitSum(n%1000)\nоқу K\nK рет: оқу билет; isLucky нәтижесін шығару","pseudo_ru":"digitSum(n): выделить и сложить цифры\nisLucky(n): digitSum(n/1000)=digitSum(n%1000)\nпрочитать K\nK раз: прочитать билет; вывести результат isLucky",
      "solution":"#include <iostream>\nusing namespace std;\nint sum(int n){ int s=0; while(n){s+=n%10; n/=10;} return s; }\nbool lucky(int n){ return sum(n/1000)==sum(n%1000); }\nint main(){ int k,n; cin>>k; while(k--){cin>>n; cout<<(lucky(n)?\"YES\":\"NO\")<<'\\n';} }"
    },
    {
      "module":"Сортировка","title":"Квадраттық сұрыптау","title_ru":"Квадратичная сортировка","position":0,"grade":8,"duration":"75 минут",
      "summary":"Көпіршік және таңдау арқылы сұрыптау алгоритмдері, олардың O(n²) күрделілігі және ауыстыру операциясы.","summary_ru":"Сортировки пузырьком и выбором, обмен элементов и квадратичная сложность O(n²).",
      "theory":["Көпіршік сұрыптауда көрші элементтер салыстырылып, реті қате болса орын ауысады.","Таңдау сұрыптауы әр кезеңде ең кіші немесе ең үлкен элементті дұрыс орынға қояды.","Екі алгоритмнің ең нашар жағдайдағы күрделілігі O(n²).","Сұрыптаудан кейін массивтің өсу немесе кему реті анық болуы керек."],
      "theory_ru":["В пузырьковой сортировке сравниваются соседние элементы и меняются местами при неверном порядке.","В сортировке выбором на каждом шаге нужный минимум или максимум ставится на позицию.","Худшая сложность обоих алгоритмов — O(n²).","После сортировки явно проверьте, по возрастанию или убыванию упорядочен массив."],
      "algorithm":["Массивті оқыңыз.","Көрші элементтерді немесе қалған бөліктің минимумын салыстырыңыз.","Қажет болса swap арқылы орын ауыстырыңыз.","Барлық позициялар өңделгенше қайталаңыз."],
      "algorithm_ru":["Прочитайте массив.","Сравнивайте соседние элементы или ищите минимум в оставшейся части.","При необходимости выполните swap.","Повторяйте, пока все позиции не будут обработаны."],
      "code":"#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){ int n; cin>>n; vector<int>a(n); for(int&x:a)cin>>x;\n  for(int i=0;i<n;i++) for(int j=0;j+1<n-i;j++) if(a[j]>a[j+1]) swap(a[j],a[j+1]);\n  for(int x:a) cout<<x<<' '; }",
      "tasks":["A. Көпіршік тәсілімен сұрыптау","B. Таңдау арқылы сұрыптау","C. Құмарпаз Шрэк","D. Уақытты сұрыптау","E. Сайлау","F. Той","G. Жылдық баланс","H. Массаларды сұрыптау","I. Жұмыс уақыты"],
      "tasks_ru":["A. Сортировка пузырьком","B. Сортировка выбором","C. Азартный Шрек","D. Сортировка времени","E. Выборы","F. Праздник","G. Годовой баланс","H. Сортировка масс","I. Время работы"],
      "statement":"N бүтін саннан тұратын массивті көпіршік әдісімен өсу ретімен сұрыптаңыз. Әр қадамда көрші элементтердің реті дұрыс болмаса, оларды ауыстырыңыз.\n\nКіріс деректері: N және массив элементтері.\n\nШығыс деректері: сұрыпталған массивті шығарыңыз.\n\nМысал: Кіріс: 5; 4 1 3 2 5. Шығыс: 1 2 3 4 5.",
      "statement_ru":"Отсортируйте массив из N целых чисел методом пузырька по возрастанию. На каждом шаге меняйте соседние элементы, если они стоят в неправильном порядке.\n\nВходные данные: N и элементы массива.\n\nВыходные данные: выведите отсортированный массив.\n\nПример: вход: 5; 4 1 3 2 5. Выход: 1 2 3 4 5.",
      "explanation":"Әр өтуде үлкен элементтер массивтің соңына қарай жылжиды. i циклінен кейін соңғы i элемент дұрыс орнында болады.","explanation_ru":"На каждом проходе большие элементы перемещаются к концу. После i-го прохода последние i элементов уже стоят на своих местах.",
      "data":"vector<int> a; int n, i, j.","data_ru":"vector<int> a; int n, i, j.","pseudo":"оқу a\nfor i=0..n-1\n  for j=0..n-i-2\n    егер a[j]>a[j+1] болса swap\nшығару a","pseudo_ru":"прочитать a\nдля i=0..n-1\n  для j=0..n-i-2\n    если a[j]>a[j+1], выполнить swap\nвывести a",
      "solution":"#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){int n;cin>>n;vector<int>a(n);for(int&x:a)cin>>x;for(int i=0;i<n;i++)for(int j=0;j+1<n-i;j++)if(a[j]>a[j+1])swap(a[j],a[j+1]);for(int x:a)cout<<x<<' ';}"
    },
    {
      "module":"Сортировка","title":"Жылдам сұрыптау","title_ru":"Быстрая сортировка","position":1,"grade":9,"duration":"75 минут",
      "summary":"Санақ арқылы сұрыптау және жылдам сұрыптаудың идеясы: массивті бөліктерге бөліп өңдеу.","summary_ru":"Сортировка подсчётом и идея быстрой сортировки: разделение массива на части.",
      "theory":["Санақ арқылы сұрыптау мәндер диапазоны шағын болғанда тиімді.","Жылдам сұрыптау pivot элементін таңдап, кіші және үлкен элементтерді екі бөлікке бөледі.","Жақсы бөлінген жағдайда quicksort орташа O(n log n) жұмыс істейді.","Pivot-ті нашар таңдау ең нашар O(n²) жағдайына әкелуі мүмкін."],
      "theory_ru":["Сортировка подсчётом эффективна, когда диапазон значений небольшой.","Quicksort выбирает pivot и разделяет элементы на меньшие и большие.","При хорошем разделении средняя сложность quicksort — O(n log n).","Неудачный pivot может привести к худшему случаю O(n²)."],
      "algorithm":["Pivot таңдап, солдан кіші және оңнан үлкен элементтерді іздеңіз.","Бөліктерді орын ауыстыру арқылы бөлу аяқталғанша жалғастырыңыз.","Сол және оң ішкі массивтерге рекурсивті қолданыңыз.","Базалық жағдай: ішкі массив ұзындығы 0 немесе 1."],
      "algorithm_ru":["Выберите pivot и ищите элементы, нарушающие порядок слева и справа.","Меняйте их местами, пока разбиение не завершится.","Рекурсивно обработайте левую и правую части.","База: длина части равна 0 или 1."],
      "code":"#include <algorithm>\n#include <iostream>\n#include <vector>\nusing namespace std;\nvoid quicksort(vector<int>& a,int l,int r){ if(l>=r)return; int i=l,j=r,p=a[(l+r)/2]; while(i<=j){while(a[i]<p)i++;while(a[j]>p)j--;if(i<=j)swap(a[i++],a[j--]);} quicksort(a,l,j); quicksort(a,i,r); }\nint main(){int n;cin>>n;vector<int>a(n);for(int&x:a)cin>>x;quicksort(a,0,n-1);for(int x:a)cout<<x<<' ';}",
      "tasks":["A. Санақ арқылы сұрыптау","B. Арифметикалық прогрессия - 2","C. Ең жақын нүктелер","D. Тізбекті түрлендіру"],
      "tasks_ru":["A. Сортировка подсчётом","B. Арифметическая прогрессия - 2","C. Ближайшие точки","D. Преобразование последовательности"],
      "statement":"N бүтін саннан тұратын массивті санақ арқылы сұрыптаңыз. Элементтер 0-ден 100-ге дейінгі диапазонда орналасқан.\n\nКіріс деректері: N және массив.\n\nШығыс деректері: массив элементтерін өсу ретімен шығарыңыз.\n\nМысал: Кіріс: 6; 3 1 2 3 0 1. Шығыс: 0 1 1 2 3 3.",
      "statement_ru":"Отсортируйте массив из N целых чисел методом подсчёта. Все элементы находятся в диапазоне от 0 до 100.\n\nВходные данные: N и массив.\n\nВыходные данные: выведите элементы по возрастанию.\n\nПример: вход: 6; 3 1 2 3 0 1. Выход: 0 1 1 2 3 3.",
      "explanation":"Әр мәннің кездесу санын count массивінде сақтаймыз. Содан соң мәндерді count санына сәйкес қайта шығарамыз; салыстыру қажет емес.","explanation_ru":"В массиве count храним частоту каждого значения. Затем выводим каждое значение нужное число раз — сравнения между элементами не нужны.",
      "data":"int count[101]; vector<int> a.","data_ru":"int count[101]; vector<int> a.","pseudo":"count[0..100] ← 0\nәр x үшін count[x]++\nvalue=0..100: count[value] рет шығару","pseudo_ru":"count[0..100] ← 0\nдля каждого x: count[x]++\nдля value=0..100 вывести value count[value] раз",
      "solution":"#include <iostream>\nusing namespace std;\nint main(){int n,x,c[101]={};cin>>n;while(n--){cin>>x;c[x]++;}for(int v=0;v<=100;v++)while(c[v]--)cout<<v<<' ';}"
    },
    {
      "module":"Сортировка","title":"Құрылымдарды сұрыптау","title_ru":"Сортировка структур","position":2,"grade":9,"duration":"75 минут",
      "summary":"Объектілер массивін бірнеше өріс бойынша comparator көмегімен сұрыптау.","summary_ru":"Сортировка массива объектов по одному или нескольким полям с помощью компаратора.",
      "theory":["struct объектінің бірнеше қасиетін бір жазбаға біріктіреді.","Сұрыптау үшін салыстыру ережесін comparator функциясында анықтаймыз.","Бірінші өріс тең болса, екінші өріс бойынша салыстыруға болады.","Тұрақты сұрыптау қажет болса stable_sort қолданыңыз."],
      "theory_ru":["struct объединяет несколько свойств объекта в одну запись.","Правило сравнения задаётся в функции-компараторе.","Если первое поле равно, можно сравнить второе поле.","Для сохранения порядка равных элементов используйте stable_sort."],
      "algorithm":["Құрылым өрістерін анықтаңыз.","Массивті оқыңыз.","Сұрыптау кілтін таңдап comparator жазыңыз.","sort немесе stable_sort қолданып, нәтижені шығарыңыз."],
      "algorithm_ru":["Определите поля структуры.","Прочитайте массив объектов.","Выберите ключ сортировки и напишите компаратор.","Используйте sort или stable_sort и выведите результат."],
      "code":"#include <algorithm>\n#include <iostream>\n#include <vector>\nusing namespace std;\nstruct Exam { string name; int score; };\nint main(){ int n;cin>>n;vector<Exam>a(n);for(auto&x:a)cin>>x.name>>x.score; sort(a.begin(),a.end(),[](const Exam&x,const Exam&y){return x.score>y.score;}); for(auto&x:a)cout<<x.name<<' '; }",
      "tasks":["A. Емтихандар","B. Оқушылар","C. Ұзындыққа секіру"],
      "tasks_ru":["A. Экзамены","B. Ученики","C. Прыжки в длину"],
      "statement":"N оқушының аты және емтихан ұпайы берілген. Оқушыларды ұпайы кему ретімен сұрыптап, аттарын шығарыңыз. Ұпайлары тең болса, бастапқы ретін сақтаңыз.\n\nКіріс деректері: N, одан кейін N жолда аты және ұпайы.\n\nШығыс деректері: сұрыпталған оқушылардың аттарын шығарыңыз.\n\nМысал: Кіріс: 3; Ayan 90; Dana 95; Miras 90. Шығыс: Dana Ayan Miras.",
      "statement_ru":"Даны имена и баллы N учеников. Отсортируйте учеников по убыванию балла и выведите имена. При равных баллах сохраните исходный порядок.\n\nВходные данные: N, затем N строк с именем и баллом.\n\nВыходные данные: выведите имена в отсортированном порядке.\n\nПример: вход: 3; Ayan 90; Dana 95; Miras 90. Выход: Dana Ayan Miras.",
      "explanation":"Әр оқушыны аты мен ұпайы бірге сақталатын құрылым ретінде қарастырамыз. stable_sort тең ұпайлы оқушылардың бастапқы ретін бұзбайды.","explanation_ru":"Имя и балл храним вместе в структуре. stable_sort сохраняет исходный порядок учеников с одинаковым баллом.",
      "data":"struct Student { string name; int score; }; vector<Student>.","data_ru":"struct Student { string name; int score; }; vector<Student>.","pseudo":"оқу Student массиві\nstable_sort: score үлкені алдымен\nшығару name","pseudo_ru":"прочитать массив Student\nstable_sort: больший score раньше\nвывести name",
      "solution":"#include <algorithm>\n#include <iostream>\n#include <vector>\nusing namespace std;\nstruct Student{string name;int score;};\nint main(){int n;cin>>n;vector<Student>a(n);for(auto&x:a)cin>>x.name>>x.score;stable_sort(a.begin(),a.end(),[](auto&x,auto&y){return x.score>y.score;});for(auto&x:a)cout<<x.name<<' ';}"
    },
    {
      "module":"Двумерные массивы","title":"Негізгі операциялар","title_ru":"Базовые операции","position":0,"grade":8,"duration":"75 минут",
      "summary":"Екі өлшемді массивті оқу, жолдар мен бағандарды өңдеу, транспозиция және матрицалар амалдары.","summary_ru":"Чтение матрицы, обработка строк и столбцов, транспонирование и операции над матрицами.",
      "theory":["Матрица a[i][j] индексі арқылы i-жол және j-баған элементін береді.","Екі қабатты цикл барлық элементті қарап шығудың негізгі тәсілі.","Транспозицияда a[i][j] мәні b[j][i] орнына көшеді.","Матрицаларды қосқанда өлшемдері бірдей болуы керек, көбейткенде ішкі өлшемдер сәйкес болуы керек."],
      "theory_ru":["Элемент a[i][j] находится на строке i и столбце j.","Два вложенных цикла — основной способ пройти все элементы матрицы.","При транспонировании a[i][j] переходит в b[j][i].","Для сложения размеры матриц должны совпадать, для умножения совпадают внутренние размеры."],
      "algorithm":["Жолдар мен бағандар санын оқыңыз.","Екі циклмен матрицаны енгізіңіз.","Қажетті операцияны әр элементке қолданыңыз.","Нәтижені жол бойынша шығарыңыз."],
      "algorithm_ru":["Прочитайте число строк и столбцов.","Введите матрицу двумя циклами.","Примените нужную операцию к элементам.","Выведите результат построчно."],
      "code":"#include <iostream>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;int a[100][100];for(int i=0;i<n;i++)for(int j=0;j<m;j++)cin>>a[i][j];for(int j=0;j<m;j++){for(int i=0;i<n;i++)cout<<a[i][j]<<' ';cout<<'\\n';}}",
      "tasks":["A. Екі өлшемді массив","B. Транспозициялау - 1","C. Транспозициялау - 2","D. Транспозициялау - 3","E. Транспозициялау - 4","F. Матрицалар қосындысы","G. Матрицалардың көбейтіндісі","H. Матрицаны бұру"],
      "tasks_ru":["A. Двумерный массив","B. Транспонирование - 1","C. Транспонирование - 2","D. Транспонирование - 3","E. Транспонирование - 4","F. Сумма матриц","G. Произведение матриц","H. Поворот матрицы"],
      "statement":"N×M өлшемді матрицаны транспозициялаңыз: бастапқы матрицаның i-жолындағы j-элемент нәтиже матрицасының j-жолындағы i-элементі болады.\n\nКіріс деректері: N, M және матрица элементтері.\n\nШығыс деректері: транспозицияланған матрицаны шығарыңыз.\n\nМысал: Кіріс: 2 3; 1 2 3; 4 5 6. Шығыс: 1 4; 2 5; 3 6.",
      "statement_ru":"Транспонируйте матрицу размера N×M: элемент строки i и столбца j исходной матрицы становится элементом строки j и столбца i новой матрицы.\n\nВходные данные: N, M и элементы матрицы.\n\nВыходные данные: выведите транспонированную матрицу.\n\nПример: вход: 2 3; 1 2 3; 4 5 6. Выход: 1 4; 2 5; 3 6.",
      "explanation":"Транспозиция кезінде индекстердің орны ауысады: a[i][j] → b[j][i]. Сондықтан сыртқы циклді бағандармен жүргізу жеткілікті.","explanation_ru":"При транспонировании индексы меняются местами: a[i][j] → b[j][i]. Поэтому внешний цикл можно вести по столбцам исходной матрицы.",
      "data":"int a[100][100]; int n, m, i, j.","data_ru":"int a[100][100]; int n, m, i, j.","pseudo":"оқу n, m және a\nfor j=0..m-1\n  for i=0..n-1: шығару a[i][j]\nжол соңын шығару","pseudo_ru":"прочитать n, m и a\nдля j=0..m-1\n  для i=0..n-1: вывести a[i][j]\nперейти на новую строку",
      "solution":"#include <iostream>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;int a[100][100];for(int i=0;i<n;i++)for(int j=0;j<m;j++)cin>>a[i][j];for(int j=0;j<m;j++){for(int i=0;i<n;i++)cout<<a[i][j]<<' ';cout<<'\\n';}}"
    },
    {
      "module":"Двумерные массивы","title":"Таңбалық матрицалар","title_ru":"Символьные матрицы","position":1,"grade":8,"duration":"75 минут",
      "summary":"Символдық матрицаларды оқу және көршілес ұяшықтар, өрнектер, ойын тақталары арқылы талдау.","summary_ru":"Обработка символьных матриц, соседних клеток, узоров и игровых полей.",
      "theory":["Символдық матрица char типті элементтерден тұрады.","Ұяшық көршілерін тексергенде шекарадан шықпау керек.","Тақтадағы нысанды символ арқылы белгілеуге болады: #, ., *, X.","Күрделі өрнек есептерінде жол, баған және диагональдарды жеке талдаңыз."],
      "theory_ru":["Символьная матрица состоит из элементов типа char.","При проверке соседей нельзя выходить за границы матрицы.","Объекты на поле можно обозначать символами #, ., *, X.","В задачах с узорами отдельно анализируйте строки, столбцы и диагонали."],
      "algorithm":["Матрица өлшемін және символдарын оқыңыз.","Әр ұяшық үшін қажетті көршілер координаталарын есептеңіз.","Шекаралық ұяшықтарды бөлек тексеріңіз.","Нәтиже матрицасын немесе есептелген санды шығарыңыз."],
      "algorithm_ru":["Прочитайте размеры и символы матрицы.","Для каждой клетки вычислите координаты нужных соседей.","Отдельно обработайте клетки на границе.","Выведите новую матрицу или вычисленное значение."],
      "code":"#include <iostream>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;char a[100][100];for(int i=0;i<n;i++)for(int j=0;j<m;j++)cin>>a[i][j];for(int i=0;i<n;i++){for(int j=0;j<m;j++)cout<<(a[i][j]=='#'?'X':'.');cout<<'\\n';}}",
      "tasks":["A. Әдемі өрнек","B. Миша және негатив","C. Теңіз шайқасы - 2","D. Қалалар - 2","E. Табло","F. «Өмір» ойыны"],
      "tasks_ru":["A. Красивый узор","B. Миша и негатив","C. Морской бой - 2","D. Города - 2","E. Табло","F. Игра «Жизнь»"],
      "statement":"N×M таңбалық сурет берілген. Суреттегі # символдарын X символына, қалған ұяшықтарды нүктеге ауыстырып шығарыңыз.\n\nКіріс деректері: N, M және таңбалар матрицасы.\n\nШығыс деректері: түрлендірілген матрицаны шығарыңыз.\n\nМысал: Кіріс: 2 3; #..; .#. Шығыс: X..; .X.",
      "statement_ru":"Дана символьная картинка размера N×M. Замените каждый символ # на X, а остальные клетки — на точку.\n\nВходные данные: N, M и матрица символов.\n\nВыходные данные: выведите преобразованную матрицу.\n\nПример: вход: 2 3; #..; .#. Выход: X..; .X.",
      "explanation":"Әр ұяшық тәуелсіз өңделеді: # болса X, басқа кез келген символ болса . шығарамыз. Матрицаны сақтамай-ақ бірден шығара аламыз.","explanation_ru":"Каждая клетка обрабатывается независимо: для # выводим X, для любого другого символа — точку. Хранить вторую матрицу необязательно.",
      "data":"char a[100][100]; int n, m.","data_ru":"char a[100][100]; int n, m.","pseudo":"оқу n, m\nfor әр i,j: оқу a[i][j]\nегер a[i][j]='#' болса X, әйтпесе . шығару","pseudo_ru":"прочитать n, m\nдля каждого i,j: прочитать a[i][j]\nесли a[i][j]=='#', вывести X, иначе .",
      "solution":"#include <iostream>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;for(int i=0;i<n;i++){for(int j=0;j<m;j++){char c;cin>>c;cout<<(c=='#'?'X':'.');}cout<<'\\n';}}"
    },
    {
      "module":"Двумерные массивы","title":"Бүтін санды матрицалар","title_ru":"Целочисленные матрицы","position":2,"grade":9,"duration":"90 минут",
      "summary":"Бүтін матрицалардағы минимум, максимум, ершік нүктелері, спираль және күрделі амалдар.","summary_ru":"Минимумы, максимумы, седловые точки, спираль и сложные операции над целочисленными матрицами.",
      "theory":["Әр жол мен бағанды жеке қарап, локалды минимум немесе максимум табуға болады.","Матрицаны спиральмен толтыруда төрт шекараны: top, bottom, left, right сақтаңыз.","Матрица көбейтіндісінде үш цикл қолданылады: i, j және ортақ k.","Ершік нүкте — өз жолындағы ең кіші әрі өз бағанындағы ең үлкен элемент сияқты арнайы шартпен тексеріледі."],
      "theory_ru":["Минимум или максимум в строке и столбце можно искать отдельными проходами.","Для спирали удобно хранить четыре границы: top, bottom, left, right.","При умножении матриц используются три цикла: i, j и общий индекс k.","Седловую точку проверяют по условию минимума строки и максимума столбца или наоборот."],
      "algorithm":["Матрица өлшемін және элементтерін оқыңыз.","Есепке қажетті жолдық және бағандық сипаттамаларды есептеңіз.","Әр кандидат үшін шарттың барлық бөлігін тексеріңіз.","Нәтижені талап етілген форматта шығарыңыз."],
      "algorithm_ru":["Прочитайте размеры и элементы матрицы.","Вычислите нужные свойства строк и столбцов.","Для каждого кандидата проверьте все части условия.","Выведите результат в требуемом формате."],
      "code":"#include <iostream>\nusing namespace std;\nint main(){int n,m;cin>>n>>m;int a[100][100];for(int i=0;i<n;i++)for(int j=0;j<m;j++)cin>>a[i][j];for(int i=0;i<n;i++){int mn=a[i][0];for(int j=1;j<m;j++)mn=min(mn,a[i][j]);cout<<mn<<' ';}}",
      "tasks":["A. Сапер","B. Суретші","C. Симпатиялылықты тексеру","D. Ершік нүктелері","E. Ойындар теориясы","F. Судоку","G. Спираль","H. Жылан","I. Винни-пух","J. Матрица: Перезагрузка","K. Магический квадрат"],
      "tasks_ru":["A. Сапёр","B. Художник","C. Проверка симпатичности","D. Седловые точки","E. Теория игр","F. Судоку","G. Спираль","H. Змейка","I. Винни-Пух","J. Матрица: Перезагрузка","K. Магический квадрат"],
      "statement":"N×N матрицаны 1-ден N²-ге дейінгі сандармен сағат тілі бағытымен спираль түрінде толтырыңыз. Спираль сол жақ жоғарғы бұрыштан басталады.\n\nКіріс деректері: N (2≤N≤100).\n\nШығыс деректері: спиральмен толтырылған матрицаны шығарыңыз.\n\nМысал: Кіріс: 3. Шығыс: 1 2 3; 8 9 4; 7 6 5.",
      "statement_ru":"Заполните матрицу N×N числами от 1 до N² по спирали по часовой стрелке. Спираль начинается в левом верхнем углу.\n\nВходные данные: N (2≤N≤100).\n\nВыходные данные: выведите матрицу, заполненную по спирали.\n\nПример: вход: 3. Выход: 1 2 3; 8 9 4; 7 6 5.",
      "explanation":"Әр қабат төрт бағытпен толтырылады: жоғарғы жол, оң жақ баған, төменгі жол, сол жақ баған. Әр қабаттан кейін төрт шекараны ішке жылжытамыз.","explanation_ru":"Каждый слой заполняется в четыре стороны: верхняя строка, правый столбец, нижняя строка, левый столбец. После слоя границы сдвигаются внутрь.",
      "data":"int a[100][100]; int top, bottom, left, right, value.","data_ru":"int a[100][100]; int top, bottom, left, right, value.","pseudo":"top=0,bottom=n-1,left=0,right=n-1,value=1\nwhile top≤bottom және left≤right: төрт бағытты толтыру\nшекараларды ішке жылжыту\nматрицаны шығару","pseudo_ru":"top=0,bottom=n-1,left=0,right=n-1,value=1\nпока top≤bottom и left≤right: заполнить четыре направления\nсдвинуть границы внутрь\nвывести матрицу",
      "solution":"#include <iostream>\nusing namespace std;\nint main(){int n;cin>>n;int a[100][100],t=0,b=n-1,l=0,r=n-1,v=1;while(t<=b&&l<=r){for(int j=l;j<=r;j++)a[t][j]=v++;t++;for(int i=t;i<=b;i++)a[i][r]=v++;r--;if(t<=b){for(int j=r;j>=l;j--)a[b][j]=v++;b--;}if(l<=r){for(int i=b;i>=t;i--)a[i][l]=v++;l++;}}for(int i=0;i<n;i++){for(int j=0;j<n;j++)cout<<a[i][j]<<' ';cout<<'\\n';}}"
    },
