  $spec$::jsonb) as x(
    module text,title text,title_ru text,position int,grade int,duration text,
    summary text,summary_ru text,theory jsonb,theory_ru jsonb,algorithm jsonb,algorithm_ru jsonb,
    code text,tasks jsonb,tasks_ru jsonb,statement text,statement_ru text,explanation text,explanation_ru text,
    data text,data_ru text,pseudo text,pseudo_ru text,solution text
  ) loop
    select m.id into v_module from public.cf_curr_modules m where m.course_id=v_course and m.title=v_spec.module limit 1;
    if v_module is null then raise exception 'Модуль табылмады: %',v_spec.module; end if;

    v_plan := jsonb_build_object('summary',v_spec.summary,'objectives',jsonb_build_array('Функция немесе алгоритмнің негізгі идеясын түсіну','Есепті қадамдарға бөлу','C++ шешімін тестілеу'),'grade',v_spec.grade,'duration',v_spec.duration);
    v_slides := jsonb_build_array(
      jsonb_build_object('type','title','pageType','slide','templateId','title','title',v_spec.title,'subtitle','ACMP: Язык программирования C++ · теория және есептер','ru',jsonb_build_object('title',v_spec.title_ru,'subtitle','ACMP: Язык программирования C++ · теория и задачи')),
      jsonb_build_object('type','content','pageType','scroll','templateId','theory','title','Негізгі түсініктер','bullets',v_spec.theory,'ru',jsonb_build_object('title','Основные понятия','bullets',v_spec.theory_ru)),
      jsonb_build_object('type','content','pageType','scroll','templateId','worked-example','title','C++ мысалы','starter',v_spec.code,'prompt','Кодты жол-жолымен оқыңыз: кіріс → негізгі әрекет → шығыс.','notes','Кодты өз тестіңізбен тексеріңіз.','ru',jsonb_build_object('title','Пример на C++','prompt','Прочитайте код по шагам: ввод → действие → вывод.','notes','Проверьте код на собственном тесте.')),
      jsonb_build_object('type','content','pageType','scroll','templateId','theory','title','Есептің алгоритмі','bullets',v_spec.algorithm,'ru',jsonb_build_object('title','Алгоритм задачи','bullets',v_spec.algorithm_ru)),
      jsonb_build_object('type','content','pageType','scroll','templateId','theory','title','PDF-тегі ACMP есептері','bullets',v_spec.tasks,'prompt','Бұл тақырыптағы есептер PDF-тегі есептер көрсеткішінен алынды.','ru',jsonb_build_object('title','Задачи ACMP из PDF','bullets',v_spec.tasks_ru,'prompt','Названия задач взяты из указателя PDF.')),
      jsonb_build_object('type','solution','pageType','slide','templateId','worked-example','problemPage',true,'answerHidden',true,'title',v_spec.title || ' · үлгі есеп','sections',jsonb_build_array(
        jsonb_build_object('h','Есептің берілуі','text',v_spec.statement),jsonb_build_object('h','Есептің түсіндірілуі','text',v_spec.explanation),jsonb_build_object('h','Есептің алгоритмі','text',(select string_agg(value,E'\n' order by ord) from jsonb_array_elements_text(v_spec.algorithm) with ordinality as t(value,ord))),jsonb_build_object('h','Деректер құрылымы','text',v_spec.data),jsonb_build_object('h','Псевдокод','text',v_spec.pseudo),jsonb_build_object('h','Есептің шешімі (жасырын)','hide',true,'code',v_spec.solution,'lang','C++')
      ),'ru',jsonb_build_object('title',v_spec.title_ru || ' · пример задачи','problemPage',true,'answerHidden',true,'sections',jsonb_build_array(
        jsonb_build_object('h','Условие задачи','text',v_spec.statement_ru),jsonb_build_object('h','Объяснение задачи','text',v_spec.explanation_ru),jsonb_build_object('h','Алгоритм задачи','text',(select string_agg(value,E'\n' order by ord) from jsonb_array_elements_text(v_spec.algorithm_ru) with ordinality as t(value,ord))),jsonb_build_object('h','Структура данных','text',v_spec.data_ru),jsonb_build_object('h','Псевдокод','text',v_spec.pseudo_ru),jsonb_build_object('h','Решение задачи (скрыто)','hide',true,'code',v_spec.solution,'lang','C++')
      )))
    );
    v_terms := jsonb_build_array(jsonb_build_object('term',v_spec.title,'definition',v_spec.summary),jsonb_build_object('term','алгоритм','definition','Есепті шешуге апаратын реттелген әрекеттер тізбегі.'));
    select l.id into v_lesson from public.cf_lessons l where l.owner_id=v_owner and l.title=v_spec.title limit 1;
    if v_lesson is null then
      insert into public.cf_lessons(school_id,owner_id,title,subject,plan,slides,terms) values(v_school,v_owner,v_spec.title,'Информатика олимпиадасы',v_plan,v_slides,v_terms) returning id into v_lesson;
    else
      update public.cf_lessons set subject='Информатика олимпиадасы',plan=v_plan,slides=v_slides,terms=v_terms,updated_at=now() where id=v_lesson;
    end if;
    insert into public.cf_curr_lessons(lesson_id,module_id,position) values(v_lesson,v_module,v_spec.position) on conflict(lesson_id) do update set module_id=excluded.module_id,position=excluded.position;
    v_module:=null;v_lesson:=null;
  end loop;
end;
$acmp_advanced$;
